exec(compile('"""범용 보고서 v2의 데스크톱 설정 화면. tkinter 외 별도 GUI 패키지 불필요."""\nimport json\nfrom pathlib import Path\n\n\ndef describe_plan(plan):\n    """JSON 설정을 사용자가 검토할 수 있는 한글 설명으로 바꾼다."""\n    aggregate_names = {"sum": "합계", "count": "건수", "avg": "평균", "min": "최소", "max": "최대"}\n    pivot_names = {"value": "값 그대로", "month": "월", "yearmonth": "연월", "year": "연도"}\n    lines = []\n    for i, mapping in enumerate(plan.get("mappings", []), 1):\n        source = {**plan.get("source", {}), **mapping.get("source", {})}\n        target = mapping.get("target", {})\n        lines.extend([f"[{i}] {mapping.get(\'id\', \'보고서 항목\')}",\n                      f"원본: {source.get(\'sheet\', \'(미지정)\')} 시트 / 제목 {source.get(\'header_row\', \'?\')}행",\n                      f"자료 범위: {source.get(\'first_data_row\') or \'제목 다음\'}행 ~ {source.get(\'last_data_row\') or \'마지막 자료\'}행"])\n        if mapping.get("mode") == "table":\n            lines.append(f"출력: {target.get(\'sheet\', \'?\')} 시트 / {target.get(\'start_cell\', \'?\')}부터 새 표 작성")\n            lines.append("행 기준: " + ", ".join(mapping.get("group_by", [])))\n            pivot = mapping.get("pivot")\n            lines.append("열 기준: " + (f"{pivot[\'column\']} ({pivot_names.get(pivot[\'kind\'], pivot[\'kind\'])})" if pivot else "없음"))\n            lines.append(f"교체 범위: {target.get(\'clear_range\') or \'(명시 안 됨)\'} / 빈 영역 확장: {\'허용\' if target.get(\'allow_expand\') else \'차단\'}")\n            lines.append(f"합계 행·열: {\'표시\' if mapping.get(\'include_totals\', True) else \'표시 안 함\'}")\n        else:\n            lines.append(f"출력: {target.get(\'sheet\', \'?\')}!{target.get(\'cell\', \'?\')}")\n        terms = mapping.get("terms", [])\n        expression = " + ".join(f"{term.get(\'column\', \'?\')} × {term.get(\'factor\', 1)}" for term in terms)\n        lines.append(f"계산: {aggregate_names.get(mapping.get(\'aggregate\'), mapping.get(\'aggregate\', \'?\'))} / {expression or \'행 수 집계\'} / 단위 {mapping.get(\'unit\', 1)}로 나눔")\n        lines.append(f"반올림: 소수 {mapping[\'round_digits\']}자리" if "round_digits" in mapping else "반올림: 별도 지정 없음")\n        lines.append(f"기존 수식 교체: {\'허용\' if mapping.get(\'allow_overwrite_formulas\') else \'차단\'}")\n        filters = mapping.get("filters", [])\n        lines.append("필터: " + (" 그리고 ".join(f"{f[\'column\']} {f[\'op\']} {f[\'value\']} ({f.get(\'type\', \'text\')})" for f in filters) if filters else "없음"))\n        lines.append("")\n    if plan.get("unresolved"):\n        lines.append("확인이 필요한 항목 — 해결 전 생성 불가:")\n        lines.extend(f"• {item}" for item in plan["unresolved"])\n    if plan.get("review_required"):\n        lines.append("검토 안내:")\n        items = plan["review_required"]\n        lines.extend(f"• {item}" for item in (items if isinstance(items, list) else [items]))\n    return "\\n".join(lines) or "연결 규칙이 없습니다."\n\n\ndef launch_gui(engine):\n    """파일/집계 조건을 명시적으로 선택한 뒤 검토·확인하여 생성한다."""\n    import tkinter as tk\n    from tkinter import ttk, filedialog, messagebox\n    from openpyxl import load_workbook\n\n    root = tk.Tk()\n    root.title("범용 엑셀 보고서 v2")\n    root.geometry("1100x950")\n    root.minsize(850, 680)\n    outer = ttk.Frame(root, padding=14)\n    outer.pack(fill="both", expand=True)\n    outer.columnconfigure(1, weight=1)\n    variables = {name: tk.StringVar() for name in\n                 ("reference", "raw", "output", "source_sheet", "target_sheet",\n                  "amount", "minus", "pivot", "clear_range", "first_data_row", "last_data_row", "round_digits")}\n    variables.update(header=tk.StringVar(value="1"), start=tk.StringVar(value="A1"),\n                     unit=tk.StringVar(value="1"), aggregate=tk.StringVar(value="합계"),\n                     pivot_kind=tk.StringVar(value="값 그대로"), mode=tk.StringVar(value="표 전체 다시 구성"))\n    totals, expand = tk.BooleanVar(value=True), tk.BooleanVar(value=False)\n    use_excel, overwrite_formulas = tk.BooleanVar(value=False), tk.BooleanVar(value=False)\n    aggregates = {"합계": "sum", "건수": "count", "평균": "avg", "최소": "min", "최대": "max"}\n    pivot_kinds = {"값 그대로": "value", "월": "month", "연월": "yearmonth", "연도": "year"}\n    status = tk.StringVar(value="기준 보고서와 원본 데이터를 선택한 뒤 [파일 구조 확인]을 누르세요.")\n    inspected = {}\n    filter_rules = []\n\n    def failure(exc):\n        status.set("진행하지 못했습니다. 표시된 항목을 확인하세요.")\n        messagebox.showerror("확인 필요", str(exc), parent=root)\n\n    def choose(name):\n        if name == "output":\n            ext = ".xlsm" if Path(variables["reference"].get()).suffix.lower() == ".xlsm" else ".xlsx"\n            path = filedialog.asksaveasfilename(parent=root, title="새 보고서 저장 위치",\n                                               defaultextension=ext, filetypes=[("Excel 통합 문서", "*" + ext)])\n        else:\n            path = filedialog.askopenfilename(parent=root, title="기준 보고서 선택" if name == "reference" else "원본 데이터 선택",\n                                             filetypes=[("Excel 통합 문서", "*.xlsx *.xlsm")])\n        if path:\n            variables[name].set(path)\n            if name != "output":\n                inspected.clear()\n                status.set("선택 파일이 바뀌었습니다. [파일 구조 확인]을 다시 누르세요.")\n\n    ttk.Label(outer, text="1. 입력 파일과 새 결과 파일", font=("", 12, "bold")).grid(row=0, column=0, columnspan=3, sticky="w")\n    for row, (name, label) in enumerate((("reference", "기준 보고서"), ("raw", "원본 데이터"), ("output", "새 보고서")), 1):\n        ttk.Label(outer, text=label).grid(row=row, column=0, sticky="w", pady=4)\n        ttk.Entry(outer, textvariable=variables[name]).grid(row=row, column=1, sticky="ew", padx=8)\n        ttk.Button(outer, text="선택…", command=lambda n=name: choose(n)).grid(row=row, column=2)\n\n    notebook = ttk.Notebook(outer)\n    notebook.grid(row=5, column=0, columnspan=3, sticky="nsew", pady=10)\n    outer.rowconfigure(5, weight=1)\n    form, advanced = ttk.Frame(notebook, padding=12), ttk.Frame(notebook, padding=8)\n    notebook.add(form, text="표 설정")\n    notebook.add(advanced, text="상세 규칙(JSON)")\n    form.columnconfigure(1, weight=1)\n    form.columnconfigure(3, weight=1)\n    combos = {}\n\n    def entry(row, column, label, name, choices=None):\n        ttk.Label(form, text=label).grid(row=row, column=column, sticky="w", padx=(0, 8), pady=5)\n        if choices is not None:\n            widget = ttk.Combobox(form, textvariable=variables[name], values=choices, state="readonly")\n            combos[name] = widget\n        else:\n            widget = ttk.Entry(form, textvariable=variables[name])\n        widget.grid(row=row, column=column + 1, sticky="ew", padx=(0, 18))\n        return widget\n\n    entry(0, 0, "원본 시트", "source_sheet", [])\n    entry(0, 2, "원본 제목 행 번호", "header")\n    entry(1, 0, "결과 시트", "target_sheet", [])\n    entry(1, 2, "시작 셀 / 갱신할 셀", "start")\n    entry(2, 0, "기존 표를 비울 범위", "clear_range")\n    entry(2, 2, "집계 방식", "aggregate", list(aggregates))\n    ttk.Label(form, text="예: A3:F20. 이 범위의 기존 내용은 새 표로 대체됩니다.", foreground="#555555").grid(row=3, column=0, columnspan=4, sticky="w")\n    ttk.Label(form, text="행으로 묶을 열(여러 개 선택 가능)").grid(row=4, column=0, columnspan=4, sticky="w", pady=(10, 3))\n    groups = tk.Listbox(form, selectmode="multiple", height=5, exportselection=False)\n    groups.grid(row=5, column=0, columnspan=4, sticky="nsew")\n    form.rowconfigure(5, weight=1)\n    entry(6, 0, "금액/값 열", "amount", [])\n    entry(6, 2, "뺄 값 열(선택)", "minus", [])\n    entry(7, 0, "열로 나눌 기준(선택)", "pivot", [])\n    entry(7, 2, "열 기준의 표시 방법", "pivot_kind", list(pivot_kinds))\n    entry(8, 0, "단위(값 ÷ 단위)", "unit")\n    ttk.Checkbutton(form, text="합계 행·열 표시", variable=totals).grid(row=8, column=2, columnspan=2, sticky="w")\n    entry(9, 0, "원본 자료 시작 행(선택)", "first_data_row")\n    entry(9, 2, "원본 자료 마지막 행(선택)", "last_data_row")\n    entry(10, 0, "반올림 소수 자릿수(선택)", "round_digits")\n    ttk.Checkbutton(form, text="기존 표의 수식 교체 허용", variable=overwrite_formulas).grid(row=10, column=2, columnspan=2, sticky="w")\n    ttk.Checkbutton(form, text="표 크기가 커지면 비어 있는 영역으로 확장 허용", variable=expand).grid(row=11, column=0, columnspan=4, sticky="w", pady=4)\n    ttk.Checkbutton(form, text="Windows Excel로 보존한 수식 재계산(pywin32 필요)", variable=use_excel).grid(row=12, column=0, columnspan=4, sticky="w", pady=4)\n    filter_summary = tk.StringVar(value="필터 없음: 원본의 모든 자료 행 대상")\n    ttk.Label(form, textvariable=filter_summary).grid(row=13, column=0, columnspan=3, sticky="w")\n    entry(15, 0, "작성 방식", "mode", ["표 전체 다시 구성", "특정 셀 값 갱신"])\n    ttk.Label(form, text="특정 셀 갱신은 행·열 기준 없이 필터로 집계 대상을 정합니다.", foreground="#555555").grid(row=16, column=0, columnspan=4, sticky="w")\n\n    rules_text = tk.Text(advanced, wrap="none", undo=True, font=("Consolas", 10))\n    scrollbar = ttk.Scrollbar(advanced, orient="vertical", command=rules_text.yview)\n    rules_text.configure(yscrollcommand=scrollbar.set)\n    rules_text.pack(side="left", fill="both", expand=True)\n    scrollbar.pack(side="right", fill="y")\n\n    def load_columns(event=None):\n        try:\n            sheet = variables["source_sheet"].get()\n            if not sheet:\n                raise ValueError("원본 시트를 선택하세요.")\n            row = int(variables["header"].get())\n            if row < 1:\n                raise ValueError("제목 행 번호는 1 이상이어야 합니다.")\n            workbook = load_workbook(variables["raw"].get(), data_only=False, read_only=True)\n            try:\n                ws = workbook[sheet]\n                headers = [str(c.value).strip() for c in ws[row] if c.value is not None and str(c.value).strip()]\n            finally:\n                workbook.close()\n            if len(set(headers)) != len(headers):\n                raise ValueError("같은 제목의 열이 있습니다. 원본에서 구분하거나 상세 규칙을 검토하세요.")\n            groups.delete(0, "end")\n            for h in headers:\n                groups.insert("end", h)\n            for name in ("amount", "minus", "pivot"):\n                combos[name]["values"] = [""] + headers\n                variables[name].set("")\n            status.set("행 기준·값 열·출력 위치를 직접 선택하세요. 자동으로 생성하지 않습니다.")\n        except Exception as exc:\n            failure(exc)\n\n    def source_changed(event=None):\n        data = inspected.get("raw", {})\n        sheet = next((s for s in data.get("sheets", []) if s["name"] == variables["source_sheet"].get()), None)\n        if sheet and sheet.get("tables"):\n            tables = sheet["tables"]\n            best = sorted(tables, key=lambda t: t.get("score", 0), reverse=True)[0]\n            variables["header"].set(str(best["header_row"]))\n            variables["first_data_row"].set(str(best.get("first_data_row") or ""))\n            # Keep future periods\' longer sources visible unless a user sets a bound.\n            variables["last_data_row"].set("")\n        load_columns()\n\n    def inspect_files():\n        try:\n            for name in ("reference", "raw"):\n                path = variables[name].get()\n                if not Path(path).is_file():\n                    raise ValueError("기준 보고서와 원본 데이터를 모두 선택하세요.")\n                inspected[name] = engine.inspect_workbook(path)\n            source_names = [s["name"] for s in inspected["raw"]["sheets"]]\n            target_names = [s["name"] for s in inspected["reference"]["sheets"]]\n            combos["source_sheet"]["values"] = source_names\n            combos["target_sheet"]["values"] = target_names\n            variables["source_sheet"].set(source_names[0] if len(source_names) == 1 else "")\n            variables["target_sheet"].set(target_names[0] if len(target_names) == 1 else "")\n            if variables["source_sheet"].get():\n                source_changed()\n            else:\n                status.set("시트가 여러 개입니다. 사용할 원본 시트와 결과 시트를 선택하세요.")\n        except Exception as exc:\n            failure(exc)\n\n    combos["source_sheet"].bind("<<ComboboxSelected>>", source_changed)\n    ttk.Button(outer, text="파일 구조 확인", command=inspect_files).grid(row=4, column=0, columnspan=3, sticky="w", pady=(6, 0))\n    ttk.Button(form, text="열 다시 읽기", command=load_columns).grid(row=14, column=0, sticky="w", pady=6)\n\n    def edit_filters():\n        dialog = tk.Toplevel(root)\n        dialog.title("필터 조건")\n        dialog.transient(root)\n        column, operator, kind, value = (tk.StringVar() for _ in range(4))\n        operator.set("=")\n        kind.set("text")\n        for i, (label, var, options) in enumerate((("원본 열", column, list(combos["amount"]["values"])), ("조건", operator, ["=", "<>", ">", "<", ">=", "<="]), ("값 종류", kind, ["text", "number", "date"]))):\n            ttk.Label(dialog, text=label).grid(row=0, column=i, padx=6)\n            ttk.Combobox(dialog, textvariable=var, values=options, state="readonly", width=20).grid(row=1, column=i, padx=6)\n        ttk.Label(dialog, text="비교할 값(날짜: YYYY-MM-DD)").grid(row=2, column=0, columnspan=3, sticky="w", padx=6)\n        ttk.Entry(dialog, textvariable=value).grid(row=3, column=0, columnspan=3, sticky="ew", padx=6)\n        listed = tk.Listbox(dialog, height=6, width=75)\n        listed.grid(row=4, column=0, columnspan=3, padx=6, pady=6)\n\n        def refresh():\n            listed.delete(0, "end")\n            for f in filter_rules:\n                listed.insert("end", f"{f[\'column\']} {f[\'op\']} {f[\'value\']} ({f[\'type\']})")\n            filter_summary.set(f"필터 {len(filter_rules)}개: 모든 조건을 만족하는 행만 집계" if filter_rules else "필터 없음: 원본의 모든 자료 행 대상")\n\n        def add():\n            if not column.get():\n                return\n            filter_rules.append({"column": column.get(), "op": operator.get(), "type": kind.get(), "value": value.get()})\n            refresh()\n\n        def remove():\n            for i in reversed(listed.curselection()):\n                del filter_rules[i]\n            refresh()\n\n        ttk.Button(dialog, text="조건 추가", command=add).grid(row=5, column=0, pady=6)\n        ttk.Button(dialog, text="선택 삭제", command=remove).grid(row=5, column=1)\n        ttk.Button(dialog, text="닫기", command=dialog.destroy).grid(row=5, column=2)\n        refresh()\n\n    ttk.Button(form, text="필터 조건…", command=edit_filters).grid(row=13, column=3, sticky="e")\n\n    def current_plan():\n        if notebook.index(notebook.select()) == 1:\n            return json.loads(rules_text.get("1.0", "end"))\n        group_columns = [groups.get(i) for i in groups.curselection()]\n        aggregate = aggregates[variables["aggregate"].get()]\n        cell_mode = variables["mode"].get() == "특정 셀 값 갱신"\n        if not group_columns and not cell_mode:\n            raise ValueError("행으로 묶을 열을 하나 이상 선택하세요.")\n        if not variables["target_sheet"].get() or not variables["source_sheet"].get():\n            raise ValueError("원본 시트와 결과 시트를 선택하세요.")\n        terms = []\n        if aggregate != "count":\n            if not variables["amount"].get():\n                raise ValueError("집계할 값 열을 선택하세요.")\n            terms.append({"column": variables["amount"].get(), "factor": 1})\n            if variables["minus"].get():\n                terms.append({"column": variables["minus"].get(), "factor": -1})\n        mapping = {"id": "표1", "mode": "table", "target": {"sheet": variables["target_sheet"].get(),\n                   "start_cell": variables["start"].get().strip(), "clear_range": variables["clear_range"].get().strip() or None,\n                   "allow_expand": bool(expand.get())}, "group_by": group_columns, "aggregate": aggregate,\n                   "terms": terms, "filters": list(filter_rules), "unit": variables["unit"].get().strip(),\n                   "include_totals": bool(totals.get()), "sort": "source", "allow_overwrite_formulas": bool(overwrite_formulas.get())}\n        if variables["round_digits"].get().strip():\n            mapping["round_digits"] = int(variables["round_digits"].get())\n        if cell_mode:\n            mapping["mode"] = "cells"\n            mapping["target"] = {"sheet": variables["target_sheet"].get(), "cell": variables["start"].get().strip()}\n            for key in ("group_by", "include_totals", "sort"):\n                mapping.pop(key, None)\n        elif variables["pivot"].get():\n            mapping["pivot"] = {"column": variables["pivot"].get(), "kind": pivot_kinds[variables["pivot_kind"].get()]}\n        source = {"sheet": variables["source_sheet"].get(), "header_row": int(variables["header"].get())}\n        for name in ("first_data_row", "last_data_row"):\n            if variables[name].get().strip():\n                source[name] = int(variables[name].get())\n        return {"version": 2, "approved": False, "source": source, "mappings": [mapping], "unresolved": []}\n\n    def set_json(plan):\n        rules_text.delete("1.0", "end")\n        rules_text.insert("1.0", json.dumps(plan, ensure_ascii=False, indent=2))\n\n    def preview_and_generate():\n        try:\n            reference, raw, output = (variables[n].get() for n in ("reference", "raw", "output"))\n            if not all((reference, raw, output)):\n                raise ValueError("기준 보고서·원본·새 보고서 저장 위치를 모두 선택하세요.")\n            if Path(output).exists() or Path(output).is_symlink():\n                raise ValueError("새 보고서 위치에 이미 파일이 있습니다. 다른 이름을 선택하세요.")\n            plan = current_plan()\n            summary = describe_plan(plan)\n            summary += "\\nWindows Excel 재계산: " + ("사용" if use_excel.get() else "사용 안 함 — 보존한 수식은 별도 재계산 필요")\n            # Human approval is bound to the exact reviewed configuration by the engine.\n            review = tk.Toplevel(root)\n            review.title("생성 설정 검토")\n            review.geometry("850x650")\n            review.transient(root)\n            review.grab_set()\n            ttk.Label(review, text=f"기준: {Path(reference).name}\\n원본: {Path(raw).name}\\n결과: {output}", padding=10, wraplength=800).pack(fill="x")\n            review_text = tk.Text(review, wrap="word", font=("", 11))\n            review_text.insert("1.0", summary)\n            review_text.configure(state="disabled")\n            review_text.pack(fill="both", expand=True, padx=10)\n            approved_by_user = []\n\n            def confirm():\n                approved_by_user.append(True)\n                review.destroy()\n\n            bar = ttk.Frame(review, padding=10)\n            bar.pack(fill="x")\n            ttk.Label(bar, text="집계·출력 기준을 검토한 경우 [확인 후 생성]을 누르세요.").pack(side="left")\n            ttk.Button(bar, text="취소", command=review.destroy).pack(side="right")\n            ttk.Button(bar, text="확인 후 생성", command=confirm).pack(side="right", padx=8)\n            root.wait_window(review)\n            if not approved_by_user:\n                return\n            approved = engine.approve_plan(plan, reference, raw)\n            status.set("연결한 셀 작성 및 저장값 대조 중…")\n            root.update_idletasks()\n            result = engine.generate_report(reference, raw, approved, output, use_excel=bool(use_excel.get()))\n            set_json(approved)\n            notices = []\n            if result.get("formula_recalculation_required"):\n                notices.append("보존한 수식의 계산 결과는 아직 대조하지 않았습니다. Excel에서 열어 전체 재계산 후 저장해야 합니다.")\n            unmapped = result.get("unmapped_numeric_cells", [])\n            if unmapped:\n                sample = "\\n".join(f"{item.get(\'sheet\', \'?\')}!{item.get(\'cell\', \'?\')} : {item.get(\'value\', \'\')}" if isinstance(item, dict) else str(item) for item in unmapped[:20])\n                notices.append(f"기존 보고서의 연결되지 않은 숫자 {len(unmapped)}칸이 그대로 남아 있습니다. 새 원본과 대조한 결과가 아니므로 확인이 필요합니다.\\n{sample}" + ("\\n…" if len(unmapped) > 20 else ""))\n            complete = f"연결한 {result.get(\'cells_written\', \'\')}칸 작성·저장값 대조 완료"\n            if notices:\n                status.set(f"{complete} / 추가 확인 필요: {output}")\n                messagebox.showwarning("연결한 셀 작성 완료 — 추가 확인 필요", f"{complete}\\n{output}\\n\\n" + "\\n\\n".join(notices), parent=root)\n            else:\n                status.set(f"{complete}: {output}")\n                messagebox.showinfo("연결한 셀 작성 완료", f"{complete}\\n{output}", parent=root)\n        except Exception as exc:\n            failure(exc)\n\n    def save_rules():\n        try:\n            plan = current_plan()\n            path = filedialog.asksaveasfilename(parent=root, title="설정 저장", defaultextension=".json", filetypes=[("JSON 설정", "*.json")])\n            if path:\n                # Saving a configuration never grants approval by itself.\n                plan["approved"] = False\n                plan.pop("approval", None)\n                Path(path).write_text(json.dumps(plan, ensure_ascii=False, indent=2), encoding="utf-8")\n                status.set(f"설정 저장: {path}")\n        except Exception as exc:\n            failure(exc)\n\n    def open_rules():\n        try:\n            path = filedialog.askopenfilename(parent=root, title="설정 열기", filetypes=[("JSON 설정", "*.json")])\n            if path:\n                set_json(json.loads(Path(path).read_text(encoding="utf-8-sig")))\n                notebook.select(advanced)\n                status.set("설정을 불러왔습니다. 입력 파일을 선택하고 설정을 검토한 뒤 생성하세요.")\n        except Exception as exc:\n            failure(exc)\n\n    def propose_rules():\n        try:\n            reference, raw = variables["reference"].get(), variables["raw"].get()\n            if not Path(reference).is_file() or not Path(raw).is_file():\n                raise ValueError("기준 보고서와 원본 데이터를 먼저 선택하세요.")\n            plan = engine.propose_plan(reference, raw)\n            plan["approved"] = False\n            plan.pop("approval", None)\n            set_json(plan)\n            notebook.select(advanced)\n            status.set("연결 후보를 가져왔습니다. 미확정 질문을 해결하고 모든 연결·계산 기준을 검토해야 생성할 수 있습니다.")\n            messagebox.showinfo("분석 결과 — 미승인 초안", describe_plan(plan), parent=root)\n        except Exception as exc:\n            failure(exc)\n\n    buttons = ttk.Frame(outer)\n    buttons.grid(row=6, column=0, columnspan=3, sticky="ew")\n    ttk.Button(buttons, text="설정 열기…", command=open_rules).pack(side="left", padx=(0, 8))\n    ttk.Button(buttons, text="설정 저장…", command=save_rules).pack(side="left")\n    ttk.Button(buttons, text="분석 결과에서 연결 후보 가져오기", command=propose_rules).pack(side="left", padx=8)\n    ttk.Button(buttons, text="설정 검토 후 보고서 생성", command=preview_and_generate).pack(side="right")\n    ttk.Label(outer, textvariable=status, wraplength=980).grid(row=7, column=0, columnspan=3, sticky="w", pady=(10, 0))\n    root.mainloop()\n\n', __file__ + ':report_ui', 'exec'), _m.__dict__)

exec(compile('"""Generic Excel report engine v2. Python 3.9+ / openpyxl.\n\nNo filename, worksheet, business account or reporting period is hardcoded.\nUse the desktop wizard with no arguments, or inspect/propose/approve/run CLI.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport copy\nimport datetime as dt\nfrom decimal import Decimal, InvalidOperation\nimport hashlib\nimport json\nimport math\nimport os\nfrom pathlib import Path\nimport re\nimport sys\nimport tempfile\nimport zipfile\n\nfrom openpyxl import load_workbook\nfrom openpyxl.cell.cell import MergedCell\nfrom openpyxl.styles import Font, PatternFill, Alignment\nfrom openpyxl.utils.cell import coordinate_to_tuple, get_column_letter, range_boundaries\nfrom openpyxl.utils.datetime import from_excel\nfrom openpyxl.workbook.properties import CalcProperties\n\nfrom report_analyzer import inspect_workbook, propose_plan\n\nVERSION = "2.0.0"\nEXCEL_ERRORS = {"#REF!", "#DIV/0!", "#VALUE!", "#NAME?", "#N/A", "#NUM!", "#NULL!", "#SPILL!", "#CALC!"}\n\n\nclass ReportError(Exception):\n    """An actionable error; output is not published when validation fails."""\n\n\ndef _fidelity_guard(path):\n    """Reject native objects that this openpyxl backend cannot preserve reliably."""\n    from xml.etree import ElementTree as ET\n    prefixes = ("xl/activeX/", "xl/ctrlProps/", "xl/slicers/", "xl/slicerCaches/",\n                "xl/threadedComments/", "xl/pivotTables/", "xl/queryTables/", "xl/externalLinks/")\n    with zipfile.ZipFile(path) as z:\n        blocked = [n for n in z.namelist() if n.startswith(prefixes) or n == "xl/connections.xml"]\n        for name in z.namelist():\n            if name.startswith(("xl/worksheets/", "xl/drawings/")) and name.endswith(".xml"):\n                root = ET.fromstring(z.read(name))\n                if any(x.tag.rsplit("}", 1)[-1] in ("extLst", "sp", "cxnSp", "grpSp") for x in root.iter()):\n                    blocked.append(name)\n        if blocked:\n            raise ReportError("기준 보고서에 이 저장 방식으로 보존을 보장할 수 없는 개체·외부연결이 있습니다. 해당 파일은 중단합니다: " + ", ".join(blocked[:4]))\n\n\ndef _sha(path):\n    h = hashlib.sha256()\n    with open(path, "rb") as f:\n        for part in iter(lambda: f.read(1024 * 1024), b""):\n            h.update(part)\n    return h.hexdigest()\n\n\ndef _digest(plan):\n    body = {k: v for k, v in plan.items() if k not in ("approval", "approved")}\n    return hashlib.sha256(json.dumps(body, ensure_ascii=False, sort_keys=True, allow_nan=False).encode()).hexdigest()\n\n\ndef _text(v):\n    if v is None:\n        return ""\n    if isinstance(v, dt.datetime):\n        return v.isoformat(sep=" ")\n    if isinstance(v, dt.date):\n        return v.isoformat()\n    if isinstance(v, float) and v.is_integer():\n        return str(int(v))\n    return str(v).strip()\n\n\ndef _numeric_or_date_like(v, epoch):\n    if isinstance(v, bool) or v is None: return False\n    if isinstance(v, (int, float, dt.date)): return True\n    if isinstance(v, str) and v.strip():\n        try:\n            _number(v)\n            return True\n        except ReportError: pass\n        try:\n            _date(v, epoch)\n            return True\n        except ReportError: pass\n    return False\n\n\ndef _number(v, location="값"):\n    if isinstance(v, bool) or v is None or isinstance(v, (dt.date, dt.time)):\n        raise ReportError(f"{location}: 숫자가 아님 ({v!r})")\n    s = str(v).strip()\n    if isinstance(v, str):\n        s = re.sub(r"[\\u200b-\\u200d\\ufeff]", "", s)\n        if s in ("-", "—", "–"):\n            return Decimal(0)\n        negative = s.startswith("(") and s.endswith(")")\n        if negative:\n            s = s[1:-1].strip()\n        if s.endswith("-"):\n            negative, s = not negative, s[:-1].strip()\n        s = s.replace("△", "-").replace("▲", "-")\n        s = re.sub(r"^([+-]?)\\s*(?:KRW|USD|₩|￦|\\$)\\s*", r"\\1", s, flags=re.I)\n        s = re.sub(r"\\s*(?:KRW|원)$", "", s, flags=re.I).strip()\n        if "," in s and not re.fullmatch(r"[+-]?\\d{1,3}(?:,\\d{3})+(?:\\.\\d+)?", s):\n            raise ReportError(f"{location}: 숫자 쉼표 형식을 확인하세요 ({v!r})")\n        s = s.replace(",", "")\n        if negative:\n            s = "-" + s\n    try:\n        d = Decimal(s)\n    except InvalidOperation:\n        raise ReportError(f"{location}: 숫자를 읽을 수 없음 ({v!r})") from None\n    if not d.is_finite():\n        raise ReportError(f"{location}: 유한한 숫자가 아님")\n    return d\n\n\ndef _date(v, epoch):\n    if isinstance(v, dt.datetime):\n        return v.date()\n    if isinstance(v, dt.date):\n        return v\n    if isinstance(v, (int, float)) and not isinstance(v, bool):\n        if 10000101 <= v <= 99991231 and float(v).is_integer():\n            v = str(int(v))\n        elif 0 <= v < 3000000:\n            try:\n                x = from_excel(v, epoch=epoch)\n            except (OverflowError, ValueError):\n                raise ReportError(f"날짜 일련번호 범위를 확인하세요: {v!r}") from None\n            if isinstance(x, dt.datetime):\n                return x.date()\n            raise ReportError(f"날짜 일련번호를 확인하세요: {v!r}")\n    s = _text(v)\n    m = re.fullmatch(r"(\\d{4})[./년-]\\s*(\\d{1,2})[./월-]\\s*(\\d{1,2})일?(?:[ T].*)?", s)\n    try:\n        if m:\n            return dt.date(*map(int, m.groups()))\n        if re.fullmatch(r"\\d{8}", s):\n            return dt.date(int(s[:4]), int(s[4:6]), int(s[6:]))\n    except ValueError:\n        pass\n    raise ReportError(f"날짜를 읽을 수 없음: {v!r}")\n\n\ndef _book(path, data=False):\n    p = Path(path)\n    if p.suffix.lower() not in (".xlsx", ".xlsm"):\n        raise ReportError("지원 파일은 xlsx / xlsm입니다. xls는 Excel에서 xlsx로 변환하세요.")\n    try:\n        return load_workbook(p, data_only=data, keep_vba=(p.suffix.lower() == ".xlsm"))\n    except Exception as exc:\n        raise ReportError(f"엑셀 파일을 열 수 없음: {p.name} ({exc})") from exc\n\n\ndef _source(raw_path, spec):\n    formulas, cached = _book(raw_path), _book(raw_path, data=True)\n    try:\n        name = spec.get("sheet")\n        if name not in formulas.sheetnames:\n            raise ReportError(f"원본 시트를 명시하세요: {name!r}")\n        ws, ds = formulas[name], cached[name]\n        hr = spec.get("header_row")\n        if not isinstance(hr, int) or hr < 1:\n            raise ReportError("원본 header_row는 1 이상 정수여야 합니다.")\n        heads = {}\n        for cell in ws[hr]:\n            if cell.value is None:\n                continue\n            label = _text(cell.value)\n            if cell.data_type == "f" or label in heads:\n                raise ReportError(f"원본 제목 중복 또는 수식: {label}")\n            heads[label] = cell.column\n        if not heads:\n            raise ReportError("원본 제목 행에 열 이름이 없습니다.")\n        first = spec.get("first_data_row") or hr + 1\n        last = spec.get("last_data_row") or ws.max_row\n        if not isinstance(first, int) or not isinstance(last, int) or first <= hr or last < first:\n            raise ReportError("원본 데이터 시작·끝 행을 확인하세요.")\n        records = []\n        for rn in range(first, last + 1):\n            if all(ws.cell(rn, c).value is None for c in heads.values()):\n                continue\n            if all(_text(ws.cell(rn, c).value) == label for label, c in heads.items()):\n                raise ReportError(f"원본 {rn}행: 제목 행이 반복됩니다. 원본 범위 또는 표 구분을 확인하세요.")\n            vals, missing = {}, set()\n            for label, col in heads.items():\n                fc, dc = ws.cell(rn, col), ds.cell(rn, col)\n                if fc.data_type == "f" and dc.value is None:\n                    missing.add(label)\n                if fc.data_type == "e" or dc.data_type == "e":\n                    missing.add(label)\n                vals[label] = dc.value\n            records.append((rn, vals, missing))\n        if not records:\n            raise ReportError("원본 데이터가 없습니다.")\n        return heads, records, formulas.epoch\n    finally:\n        formulas.close()\n        cached.close()\n\n\ndef _requirements(m):\n    cols = set(m.get("group_by", []))\n    if m.get("pivot"):\n        cols.add(m["pivot"]["column"])\n    if m.get("aggregate", "sum") != "count":\n        cols.update(t["column"] for t in m.get("terms", []))\n    cols.update(f["column"] for f in m.get("filters", []))\n    return cols\n\n\ndef _filter(row, f, epoch):\n    a, b = row[f["column"]], f.get("value")\n    typ, op = f.get("type", "text"), f.get("op", "=")\n    if typ == "text":\n        a, b = _text(a), _text(b)\n    elif typ == "number":\n        a, b = _number(a, f["column"]), _number(b, "필터 기준")\n    elif typ == "date":\n        a, b = _date(a, epoch), _date(b, epoch)\n    else:\n        raise ReportError(f"필터 type을 확인하세요: {typ}")\n    if op == "=": return a == b\n    if op in ("<>", "!="): return a != b\n    if op == ">": return a > b\n    if op == "<": return a < b\n    if op == ">=": return a >= b\n    if op == "<=": return a <= b\n    if op == "contains" and typ == "text": return b in a\n    raise ReportError(f"지원하지 않는 필터 연산자: {op}")\n\n\ndef _selected(records, m, epoch):\n    required = _requirements(m)\n    chosen = []\n    for rn, row, missing in records:\n        unavailable = required & missing\n        if unavailable:\n            raise ReportError(f"원본 {rn}행 {\', \'.join(sorted(unavailable))}: 수식 계산값 없음 또는 Excel 오류. Excel에서 재계산·저장하세요.")\n        if not all(_filter(row, f, epoch) for f in m.get("filters", [])):\n            continue\n        chosen.append((rn, row))\n    return chosen\n\n\ndef _amount(rn, row, m):\n    if m.get("aggregate", "sum") == "count":\n        return Decimal(1)\n    terms = m.get("terms", [])\n    if not terms:\n        raise ReportError("계산할 금액 열(terms)을 지정하세요.")\n    total = Decimal(0)\n    for t in terms:\n        v = row[t["column"]]\n        if v is None or (isinstance(v, str) and not v.strip()):\n            if m.get("blank_amount", "error") != "zero":\n                raise ReportError(f"원본 {rn}행 {t[\'column\']}: 금액 빈칸 (0으로 볼지는 명시해야 합니다)")\n            v = 0\n        total += _number(v, f"원본 {rn}행 {t[\'column\']}") * _number(t.get("factor", 1), "계수")\n    return total\n\n\ndef _reduce(values, m):\n    op = m.get("aggregate", "sum")\n    if op not in ("sum", "count", "avg", "min", "max"):\n        raise ReportError(f"지원 집계: sum/count/avg/min/max ({op!r})")\n    unit = _number(m.get("unit", 1), "단위")\n    if unit <= 0 or (op == "count" and unit != 1):\n        raise ReportError("단위는 양수여야 하며 건수 단위는 1이어야 합니다.")\n    if op in ("sum", "count"):\n        result = sum(values, Decimal(0))\n    elif not values:\n        raise ReportError(f"{op}: 조건에 맞는 원본 행이 없습니다.")\n    elif op == "avg":\n        result = sum(values, Decimal(0)) / len(values)\n    elif op == "min":\n        result = min(values)\n    else:\n        result = max(values)\n    result /= unit\n    if "round_digits" in m:\n        from decimal import ROUND_HALF_UP\n        digits = int(m["round_digits"])\n        if not -12 <= digits <= 12:\n            raise ReportError("반올림 자릿수 범위는 -12~12입니다.")\n        result = result.quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_UP)\n    return result\n\n\ndef _excel_number(value):\n    # Excel numeric cells cannot preserve arbitrary precision identifiers/amounts.\n    if len(value.normalize().as_tuple().digits) > 15:\n        raise ReportError("결과가 Excel 숫자의 15자리 정밀도를 넘습니다. 반올림 자릿수(round_digits)를 명시하세요.")\n    if not value.is_finite() or abs(value) > Decimal("1e308"):\n        raise ReportError("Excel에 저장할 수 없는 금액입니다.")\n    return int(value) if value == value.to_integral() else float(value)\n\n\ndef _pivot(v, spec, epoch):\n    kind = spec["kind"]\n    if kind == "value":\n        if not _text(v): raise ReportError("열 기준 값이 빈칸입니다.")\n        return _text(v)\n    d = _date(v, epoch)\n    if kind == "month": return f"{d.year:04d}-{d.month:02d}"  # year retained: no cross-year coalescing\n    if kind == "yearmonth": return f"{d.year:04d}-{d.month:02d}"\n    if kind == "year": return str(d.year)\n    raise ReportError(f"열 기준 종류를 확인하세요: {kind}")\n\n\ndef _table(m, selected, epoch):\n    groups, pivots, buckets = [], [], {}\n    by, pivot = m.get("group_by", []), m.get("pivot")\n    for rn, row in selected:\n        key = tuple(_text(row[c]) for c in by)\n        if any(not k for k in key) and m.get("blank_keys", "error") != "include":\n            raise ReportError(f"원본 {rn}행: 묶음 기준이 빈칸입니다.")\n        pk = _pivot(row[pivot["column"]], pivot, epoch) if pivot else "값"\n        if key not in groups: groups.append(key)\n        if pk not in pivots: pivots.append(pk)\n        buckets.setdefault((key, pk), []).append(_amount(rn, row, m))\n    if not groups:\n        raise ReportError("표에 집계할 원본 행이 없습니다.")\n    if pivot and pivot["kind"] != "value": pivots.sort()\n    sort = m.get("sort", "source")\n    if sort == "label": groups.sort()\n    elif sort == "amount_desc":\n        groups.sort(key=lambda k: -_reduce([v for p in pivots for v in buckets.get((k, p), [])], m))\n    elif sort != "source": raise ReportError("정렬은 source/label/amount_desc 중 하나입니다.")\n    totals = m.get("include_totals", True)\n    total_label = {"sum": "합계", "count": "총건수", "avg": "전체 평균", "min": "전체 최소", "max": "전체 최대"}[m.get("aggregate", "sum")]\n    headers = list(by) + (pivots if pivot else [m.get("value_title", m.get("aggregate", "sum"))])\n    if not by: headers = ["전체"] + headers\n    if totals and pivot: headers += [total_label]\n    grid = [headers]\n    for key in groups:\n        row = list(key) if by else ["전체"]\n        for pk in pivots:\n            vals = buckets.get((key, pk))\n            row.append(_excel_number(_reduce(vals, m)) if vals else None)\n        if totals and pivot:\n            row.append(_excel_number(_reduce([v for p in pivots for v in buckets.get((key, p), [])], m)))\n        grid.append(row)\n    if totals:\n        row = [total_label] + [None] * (max(1, len(by)) - 1)\n        for p in pivots:\n            row.append(_excel_number(_reduce([v for k in groups for v in buckets.get((k, p), [])], m)))\n        if pivot: row.append(_excel_number(_reduce([v for vs in buckets.values() for v in vs], m)))\n        grid.append(row)\n    return grid\n\n\ndef _target(wb, sheet, coordinate, mapping, planned, value):\n    if sheet not in wb.sheetnames:\n        raise ReportError(f"보고서 시트 없음: {sheet}")\n    if not isinstance(coordinate, str) or not re.fullmatch(r"[A-Za-z]{1,3}[1-9]\\d{0,6}", coordinate):\n        raise ReportError(f"단일 결과 셀 주소를 지정하세요: {coordinate!r}")\n    tr, tc = coordinate_to_tuple(coordinate)\n    if tr > 1048576 or tc > 16384:\n        raise ReportError(f"Excel 셀 범위를 넘었습니다: {coordinate}")\n    try:\n        cell = wb[sheet][coordinate]\n    except (ValueError, TypeError):\n        raise ReportError(f"결과 셀 주소를 확인하세요: {coordinate}") from None\n    if isinstance(cell, MergedCell):\n        raise ReportError(f"병합 셀의 왼쪽 위 칸에 연결하세요: {sheet}!{coordinate}")\n    if cell.data_type == "f" and not mapping.get("allow_overwrite_formulas", False):\n        raise ReportError(f"수식 덮어쓰기는 별도 확인이 필요합니다: {sheet}!{coordinate}")\n    if cell.data_type != "f" and isinstance(cell.value, str) and cell.value.strip() and not mapping.get("allow_overwrite_text", False):\n        raise ReportError(f"글자 덮어쓰기는 별도 확인이 필요합니다: {sheet}!{coordinate}")\n    key = (sheet, cell.coordinate)\n    if key in planned:\n        raise ReportError(f"결과 셀 연결 중복: {sheet}!{coordinate}")\n    planned[key] = value\n\n\ndef _validate(plan):\n    def keys(obj, allowed, label):\n        if not isinstance(obj, dict): raise ReportError(f"{label} 형식이 잘못됐습니다.")\n        extra = obj.keys() - set(allowed.split())\n        if extra: raise ReportError(f"{label}의 알 수 없는 설정: {\', \'.join(sorted(extra))}")\n    keys(plan, "version approved approval source mappings unresolved reference source_candidates report_candidates source_info review_required preserve_numeric", "규칙")\n    if plan.get("version") != 2:\n        raise ReportError("규칙 version은 2여야 합니다.")\n    if plan.get("unresolved"):\n        raise ReportError("아직 확정하지 않은 연결 기준: " + "; ".join(map(str, plan["unresolved"])))\n    if not isinstance(plan.get("source"), dict):\n        raise ReportError("원본 시트·제목 행을 지정하세요.")\n    keys(plan["source"], "sheet header_row first_data_row last_data_row", "원본 설정")\n    if not isinstance(plan.get("mappings"), list) or not plan["mappings"]:\n        raise ReportError("보고서에 연결할 항목이 없습니다.")\n    for m in plan["mappings"]:\n        keys(m, "id mode target aggregate terms filters unit group_by pivot blank_amount blank_keys include_totals sort value_title round_digits allow_overwrite_text allow_overwrite_formulas basis", "연결 설정")\n        keys(m.get("target", {}), "sheet cell start_cell clear_range allow_expand", "결과 위치")\n        for term in m.get("terms", []): keys(term, "column factor", "계산 열")\n        for f in m.get("filters", []): keys(f, "column op value type", "필터")\n        if m.get("pivot"): keys(m["pivot"], "column kind", "열 기준")\n\n\ndef _calculate(reference_path, raw_path, plan):\n    _validate(plan)\n    _fidelity_guard(reference_path)\n    wb = _book(reference_path)\n    try:\n        heads, records, epoch = _source(raw_path, plan["source"])\n        planned, stats = {}, []\n        for index, m in enumerate(plan["mappings"], 1):\n            missing = _requirements(m) - heads.keys()\n            if missing: raise ReportError("원본 열 없음: " + ", ".join(sorted(missing)))\n            selected = _selected(records, m, epoch)\n            target = m.get("target", {})\n            mode = m.get("mode", "cells")\n            if mode in ("cells", "cell"):\n                val = _excel_number(_reduce([_amount(rn, row, m) for rn, row in selected], m))\n                _target(wb, target.get("sheet"), target.get("cell"), m, planned, val)\n            elif mode == "table":\n                grid = _table(m, selected, epoch)\n                sheet = target.get("sheet")\n                if sheet not in wb.sheetnames: raise ReportError(f"보고서 시트 없음: {sheet}")\n                sr, sc = coordinate_to_tuple(target.get("start_cell", ""))\n                if not target.get("clear_range"):\n                    raise ReportError("표 교체 범위(clear_range)를 명시하세요.")\n                c1, r1, c2, r2 = range_boundaries(target["clear_range"])\n                if None in (c1, r1, c2, r2) or c2 > 16384 or r2 > 1048576 or (c2-c1+1)*(r2-r1+1) > 1000000:\n                    raise ReportError("표 교체 범위를 유효한 100만 칸 이하의 영역으로 지정하세요.")\n                if sr != r1 or sc != c1:\n                    raise ReportError("표 시작 셀과 교체 범위 왼쪽 위가 같아야 합니다.")\n                end_r, end_c = sr + len(grid) - 1, sc + len(grid[0]) - 1\n                if (end_r > r2 or end_c > c2) and not target.get("allow_expand", False):\n                    raise ReportError("새 항목이 교체 범위를 넘습니다. 확장 허용과 주변 내용을 확인하세요.")\n                # Expansion may use empty cells only, never shift other report sections.\n                for rn in range(sr, max(r2, end_r) + 1):\n                    for cn in range(sc, max(c2, end_c) + 1):\n                        if (rn > r2 or cn > c2) and wb[sheet].cell(rn, cn).value is not None:\n                            raise ReportError(f"표 확장 위치에 기존 내용이 있습니다: {sheet}!{get_column_letter(cn)}{rn}")\n                        v = grid[rn-sr][cn-sc] if rn <= end_r and cn <= end_c else None\n                        table_map = {**m, "allow_overwrite_text": True}\n                        _target(wb, sheet, f"{get_column_letter(cn)}{rn}", table_map, planned, v)\n            else: raise ReportError(f"연결 mode를 확인하세요: {mode}")\n            stats.append({"mapping": m.get("id", str(index)), "source_rows": len(records), "selected_rows": len(selected), "filtered_rows": len(records)-len(selected)})\n        return planned, stats\n    finally:\n        wb.close()\n\n\ndef approve_plan(plan, reference_path, raw_path):\n    """Called ONLY after user reviews the plan. Does not generate a workbook."""\n    result = copy.deepcopy(plan)\n    _calculate(reference_path, raw_path, result)\n    result["approved"] = True\n    result["approval"] = {"reference_sha256": _sha(reference_path), "digest": _digest(result), "version": VERSION}\n    return result\n\n\ndef verify_output(path, expected):\n    wb = _book(path)\n    try:\n        for (sheet, coord), wanted in expected.items():\n            if sheet not in wb.sheetnames:\n                raise ReportError(f"저장 검증: 시트 누락 {sheet}")\n            actual = wb[sheet][coord].value\n            if isinstance(wanted, (int, float)) and not isinstance(wanted, bool):\n                if isinstance(actual, bool) or not isinstance(actual, (int, float)) or _number(actual) != _number(wanted):\n                    raise ReportError(f"저장 검증 불일치: {sheet}!{coord} (기대 {wanted!r}, 실제 {actual!r})")\n            elif actual != wanted:\n                raise ReportError(f"저장 검증 불일치: {sheet}!{coord} (기대 {wanted!r}, 실제 {actual!r})")\n    finally:\n        wb.close()\n\n\ndef _same(a, b):\n    if Path(a).resolve() == Path(b).resolve(): return True\n    try: return os.path.samefile(a, b)\n    except OSError: return False\n\n\ndef _recalculate(path):\n    try:\n        import pythoncom\n        import win32com.client\n    except ImportError as exc:\n        raise ReportError("Excel 재계산에는 Windows Excel과 pywin32가 필요합니다.") from exc\n    pythoncom.CoInitialize()\n    app, book = None, None\n    try:\n        app = win32com.client.DispatchEx("Excel.Application")\n        app.Visible = False\n        app.DisplayAlerts = False\n        app.EnableEvents = False\n        app.AskToUpdateLinks = False\n        app.AutomationSecurity = 3  # never execute input macros\n        book = app.Workbooks.Open(str(Path(path).resolve()), UpdateLinks=0)\n        app.CalculateFullRebuild()\n        book.Save()\n        book.Close(False)\n        book = None\n    except Exception as exc:\n        raise ReportError(f"Excel 재계산 실패: {exc}") from exc\n    finally:\n        if book is not None:\n            try: book.Close(False)\n            except Exception: pass\n        if app is not None:\n            try: app.Quit()\n            except Exception: pass\n        pythoncom.CoUninitialize()\n\n\ndef generate_report(reference_path, raw_path, plan, output_path, *, use_excel=False):\n    _validate(plan)\n    if not plan.get("approved") or not plan.get("approval"):\n        raise ReportError("연결 기준을 먼저 확인·승인하세요. 미승인 규칙으로 생성하지 않습니다.")\n    approval = plan["approval"]\n    if approval.get("digest") != _digest(plan):\n        raise ReportError("승인 후 규칙이 변경됐습니다. 내용을 다시 확인·승인하세요.")\n    if approval.get("reference_sha256") != _sha(reference_path):\n        raise ReportError("기준 보고서가 변경됐습니다. 연결 기준을 다시 확인하세요.")\n    output = Path(output_path)\n    for inp in (reference_path, raw_path):\n        if _same(inp, output): raise ReportError("결과 경로가 입력 파일과 같습니다. 원본 덮어쓰기는 금지됩니다.")\n    if output.exists() or output.is_symlink(): raise ReportError("결과 파일이 이미 있습니다. 새 이름을 지정하세요.")\n    if not output.parent.is_dir(): raise ReportError("결과 저장 폴더가 없습니다.")\n    if output.suffix.lower() != Path(reference_path).suffix.lower():\n        raise ReportError("결과 확장자는 기준 보고서와 같아야 합니다 (xlsx/xlsm).")\n    before = {_text(Path(p).resolve()): _sha(p) for p in (reference_path, raw_path)}\n    expected, stats = _calculate(reference_path, raw_path, plan)\n    wb = _book(reference_path)\n    preserved, unmapped = {}, []\n    kept = {(x.get("sheet"), x.get("cell")) for x in plan.get("preserve_numeric", [])}\n    try:\n        for ws in wb:\n            for row in ws:\n                for cell in row:\n                    if cell.data_type == "f" and (ws.title, cell.coordinate) not in expected:\n                        preserved[(ws.title, cell.coordinate)] = cell.value\n                    elif (ws.title, cell.coordinate) not in expected and (ws.title, cell.coordinate) not in kept and (_numeric_or_date_like(cell.value, wb.epoch) or cell.data_type == "e"):\n                        unmapped.append({"sheet": ws.title, "cell": cell.coordinate, "value": _text(cell.value)})\n        for (sheet, coord), value in expected.items():\n            cell = wb[sheet][coord]\n            cell.value = value\n            if isinstance(value, str): cell.data_type = "s"  # no formula injection\n            if isinstance(value, (int, float)) and cell.number_format == "General": cell.number_format = "#,##0.########"\n        wb.calculation = CalcProperties(calcId=0, fullCalcOnLoad=True)\n        fd, temp = tempfile.mkstemp(prefix=".report_v2_", suffix=output.suffix, dir=output.parent)\n        os.close(fd)\n        try:\n            wb.save(temp)\n            wb.close()\n            verify_output(temp, {**preserved, **expected})\n            if use_excel:\n                _recalculate(temp)\n                verify_output(temp, expected)\n                calc = _book(temp, data=True)\n                try:\n                    for sh, co in preserved:\n                        c = calc[sh][co]\n                        if c.value is None or c.data_type == "e":\n                            raise ReportError(f"Excel 수식 계산 결과 확인 필요: {sh}!{co}")\n                finally: calc.close()\n            for inp in (reference_path, raw_path):\n                if _sha(inp) != before[_text(Path(inp).resolve())]: raise ReportError("실행 중 입력 파일이 변경됐습니다. 결과를 게시하지 않습니다.")\n            # Temp and destination share a directory/filesystem. A hard link\n            # publishes validated bytes atomically and fails if the name exists.\n            try:\n                os.link(temp, output)\n            except FileExistsError:\n                raise ReportError("저장 직전에 같은 이름의 결과 파일이 생겼습니다.") from None\n            except OSError as exc:\n                raise ReportError(f"검증한 파일을 안전하게 게시할 수 없습니다. 로컬 저장 폴더를 선택하세요: {exc}") from exc\n        finally:\n            if os.path.exists(temp): os.unlink(temp)\n    finally:\n        wb.close()\n    return {"output": str(output.resolve()), "cells_written": len(expected), "mappings": stats,\n            "formula_recalculation_required": bool(preserved) and not use_excel,\n            "formulas_preserved": len(preserved), "verified": True,\n            "unmapped_numeric_cells": unmapped,\n            "verification_scope": "mapped_values_and_preserved_formula_text",\n            "status": "수식 재계산 필요" if preserved and not use_excel else ("미연결 숫자 확인 필요" if unmapped else "연결 셀 작성·저장값 대조 완료")}\n\n\ndef main(argv=None):\n    for stream in (sys.stdout, sys.stderr):\n        try: stream.reconfigure(errors="replace")\n        except (AttributeError, ValueError): pass\n    if argv is None and len(sys.argv) == 1:\n        from report_ui import launch_gui\n        launch_gui(sys.modules[__name__])\n        return 0\n    parser = argparse.ArgumentParser(description="범용 엑셀 보고서 v2 — 먼저 연결 기준을 확인한 뒤 생성")\n    sub = parser.add_subparsers(dest="command", required=True)\n    p = sub.add_parser("inspect"); p.add_argument("file")\n    for name in ("propose", "approve", "run"):\n        p = sub.add_parser(name)\n        p.add_argument("--reference", required=True); p.add_argument("--raw", required=True)\n        p.add_argument("--out", required=True)\n        if name != "propose": p.add_argument("--rules", required=True)\n        if name == "run": p.add_argument("--excel", action="store_true")\n    args = parser.parse_args(argv)\n    try:\n        if args.command == "inspect":\n            print(json.dumps(inspect_workbook(args.file), ensure_ascii=False, indent=2)); return 0\n        if args.command == "propose": result = propose_plan(args.reference, args.raw)\n        else:\n            with open(args.rules, encoding="utf-8") as f: plan = json.load(f)\n            if args.command == "approve": result = approve_plan(plan, args.reference, args.raw)\n            else: result = generate_report(args.reference, args.raw, plan, args.out, use_excel=args.excel)\n        if args.command in ("propose", "approve"):\n            if any(_same(args.out, p) for p in (args.reference, args.raw)):\n                raise ReportError("규칙 저장 경로가 입력 파일과 같습니다.")\n            with open(args.out, "x", encoding="utf-8") as f: json.dump(result, f, ensure_ascii=False, indent=2)\n        print(json.dumps(result, ensure_ascii=False, indent=2))\n        return 2 if result.get("formula_recalculation_required") or result.get("unmapped_numeric_cells") else 0\n    except (ReportError, OSError, ValueError, KeyError, TypeError) as exc:\n        print(f"최종: 실행 중단 — {exc}", file=sys.stderr)\n        return 1\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', __file__ + ':engine', 'exec'), globals())
